 const mobile=width<600,sway=config.autonomousSway;
 const cx=width*((mobile?.68:.79)+(sway?Math.sin(time*.34)*.018:0)),cy=height*((mobile?.78:.56)+(sway?Math.cos(time*.29)*.025:0)),smooth=1-Math.exp(-dt*4);
