function draw(dt=0){if(!ctx||destroyed)return;motion==='meeting'?drawContact(dt):motion==='adaptive'?drawSolutions(dt):motion==='hub'?drawPlatform(dt):motion==='constellation'?drawAbout(dt):drawHome(dt);}
